<?php
namespace App\Filament\Resources\Facultys;
use App\Models\Faculty; use App\Filament\Resources\Facultys\Pages; use Filament\Forms\Components\{Select,TextInput}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\{Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table}; use BackedEnum; use UnitEnum;
class FacultyResource extends Resource { protected static ?string $slug='faculties'; protected static ?string $model=Faculty::class; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedBuildingOffice; protected static string|UnitEnum|null $navigationGroup='Organisasi Akademik'; protected static ?string $navigationLabel='Fakultas'; protected static ?string $modelLabel='Fakultas'; protected static ?string $pluralModelLabel='Fakultas'; public static function form(Schema $schema):Schema{return $schema->components([TextInput::make('code')->label('Kode Fakultas')->required()->unique(ignoreRecord:true)->maxLength(30),TextInput::make('name')->label('Nama Fakultas')->required()->maxLength(255),Select::make('dean_id')->label('Dekan')->relationship('dean','nidn')->searchable()->preload()->nullable()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('code')->label('Kode')->searchable()->sortable(),TextColumn::make('name')->label('Nama Fakultas')->searchable()->sortable(),TextColumn::make('dean.user.name')->label('Dekan')->placeholder('Belum ditetapkan'),TextColumn::make('departments_count')->label('Jumlah Departemen')->counts('departments')])->actions([EditAction::make()->label('Ubah'),DeleteAction::make()->label('Hapus')->requiresConfirmation()])->defaultSort('code');} public static function getPages():array{return ['index'=>Pages\ListFacultys::route('/'),'create'=>Pages\CreateFaculty::route('/create'),'edit'=>Pages\EditFaculty::route('/{record}/edit')];}}
